  "q": "Section III Writing\nPart A\n51. Directions:\nA foreign friend of yours has recently graduated from college and intends to find a job in\nChina. Write him/her an email to make some suggestions.\nYou should write about 100 words on ANSWER SHEET 2.\nDo not sign your own name at the end. Use “Li Ming” instead.\nYou do not need to write the address. (10 points)\n参考范文：\nDear Friend,\nHope this letter finds you well. I am glad to hear you intend to find a job in China, so I would\nlike to extend my warmest welcome as well as provide you with a few suggestions on job-hunting.\nFirst, you can start from listing 3 to 5 cities which you would like to work or live in. To be\nmore specific, rate them by location, working opportunities and prospects, and , of course, the\ncity’s happiness level. What’s more, be prepared for the culture shock. There is a sharp contrast in\nhow eastern people and western people work. The former prefers working individually while the\nlatter is prone to teamwork. There is one more point that, I suppose, I have to touch on: make good\nuse of online job-hunting applications, such as BOSS and 51Job.\nI hope you will find my humble suggestions be of help. I am looking forward to your reply.\nBest wishes.\nYours,\nLi Ming\nPart B\n52. Directions:\nWrite an essay of 160-200 words based on the pictures below. In your essay, you should\n1) describe the drawing briefly,\n2) explain the intended meaning, and then\n3) give your comments.\nWrite your answer on the ANSWER SHEET. (20 points)\n参考范文：\nWhat is g raphically and explicitly d epicted i n the simple yet eye-catching drawing is that on\nthe ground stands a fa ther, who i s ha ving a talk with his s on. Impressively, at se cond glance, i t is\nnot difficult to observe that the boy, dressed in a traditional Chinese costume, expresses his\nconcern about studying drama, while his father offers some words of e ncouragement.\nWithout a doubt，no boy who was born and raised in China could be ignorant that China is an\nancient nation with a l ong history an d splendid traditional culture. Traditional dramas, like Pe king\nopera, are the na tional essence of o ur culture, which are not only part of th e national heritage, but\nalso part of a liv",
